using PerspectiveV.Primitives.Types.Interfaces;
using PerspectiveV.Primitives.Types.Models;
using System.Linq.Expressions;

namespace PerspectiveV.Common.Mapper;

/// <summary>
/// Default adapter implementation of <see cref="IProjectionMapper{TEntity, TModel}"/>.
/// <para>
/// This class accepts delegates and expressions (typically generated by Mapperly) and exposes
/// a consistent entity/model API for in-memory mapping, IQueryable projection, and update operations.
/// </para>
/// <para>
/// Usage example:
/// <code><![CDATA[
/// var mapperly = new UserMapper();
///
/// IProjectionMapper<UserEntity, UserModel> mapper =
///     new ProjectionMapper<UserEntity, UserModel>(
///         mapperly.ToModel,
///         mapperly.ToEntity,
///         UserMapper.ToModelExpression(),
///         UserMapper.ToEntityExpression());
///
/// UserModel model = mapper.ToModel(entity);
/// mapper.UpdateEntity(model, entity);
/// ]]></code>
/// </para>
/// <para>
/// Explanation: this adapter keeps application code independent from a specific mapper implementation,
/// while still preserving compile-time mapping and query translation benefits.
/// </para>
/// </summary>
public class ProjectionMapper<IdType,TEntity, TModel>
    : IProjectionMapper<IdType, TEntity, TModel>
{
    private readonly Func<TEntity, TModel> _toModel;
    private readonly Func<TModel, TEntity> _toEntity;
    private readonly Expression<Func<TEntity, TModel>> _toModelExpression;
    private readonly Expression<Func<TModel, TEntity>> _toEntityExpression;
    private readonly Expression<Func<TEntity, NameValuePair<IdType>>>? _toNameValueExpression;

    /// <summary>
    /// Initializes a new instance of the <see cref="ProjectionMapper{TEntity, TModel}"/> class.
    /// </summary>
    /// <param name="toModel">Function that maps an entity to a model.</param>
    /// <param name="toEntity">Function that maps a model to an entity.</param>
    /// <param name="toModelExpression">Queryable expression for entity-to-model projection.</param>
    /// <param name="toEntityExpression">Queryable expression for model-to-entity projection.</param>
    public ProjectionMapper(
        Func<TEntity, TModel> toModel,
        Func<TModel, TEntity> toEntity,
        Expression<Func<TEntity, TModel>> toModelExpression,
        Expression<Func<TModel, TEntity>> toEntityExpression,
        Expression<Func<TEntity, NameValuePair<IdType>>>? toNameValueExpression
        )
    {
        _toModel = toModel;
        _toEntity = toEntity;
        _toModelExpression = toModelExpression;
        _toEntityExpression = toEntityExpression;

        _toNameValueExpression = toNameValueExpression;
    }

    // =========================================================
    // BASIC MAPPING
    // =========================================================

    /// <summary>
    /// Maps an entity object to a model object.
    /// </summary>
    /// <param name="source">Entity instance to map.</param>
    /// <returns>Mapped model instance.</returns>
    public TModel ToModel(TEntity source)
        => _toModel(source);

    /// <summary>
    /// Maps a model object back to an entity object.
    /// </summary>
    /// <param name="destination">Model instance to map.</param>
    /// <returns>Mapped entity instance.</returns>
    public TEntity ToEntity(TModel destination)
        => _toEntity(destination);

    // =========================================================
    // COLLECTION MAPPING
    // =========================================================

    /// <summary>
    /// Maps an entity sequence to a model sequence.
    /// </summary>
    /// <param name="source">Entity sequence to map.</param>
    /// <returns>Mapped model sequence.</returns>
    public IEnumerable<TModel> ToModelList(IEnumerable<TEntity> source)
        => source.Select(_toModel);

    /// <summary>
    /// Maps a model sequence back to an entity sequence.
    /// </summary>
    /// <param name="destination">Model sequence to map.</param>
    /// <returns>Mapped entity sequence.</returns>
    public IEnumerable<TEntity> ToEntityList(IEnumerable<TModel> destination)
        => destination.Select(_toEntity);

    // =========================================================
    // EF CORE QUERY PROJECTION
    // =========================================================

    /// <summary>
    /// Projects an entity query into a model query using the configured expression.
    /// </summary>
    /// <param name="query">Entity query to project.</param>
    /// <returns>Projected model query.</returns>
    public IQueryable<TModel> ProjectToModel(IQueryable<TEntity> query)
        => query.Select(_toModelExpression);

    /// <summary>
    /// Projects a model query into an entity query using the configured expression.
    /// </summary>
    /// <param name="query">Model query to project.</param>
    /// <returns>Projected entity query.</returns>
    public IQueryable<TEntity> ProjectToEntity(IQueryable<TModel> query)
        => query.Select(_toEntityExpression);

    // =========================================================
    // ASYNC QUERY EXECUTION HELPERS
    // =========================================================

    /// <summary>
    /// Projects and materializes model results from an entity query.
    /// Prefer provider async APIs for database queries.
    /// </summary>
    /// <param name="query">Entity query to project and execute.</param>
    /// <param name="cancellationToken">Cancellation token for the operation.</param>
    /// <returns>A task containing the projected model list.</returns>
    [Obsolete("Use ProjectToModel(query).ToListAsync(cancellationToken) to use the provider async pipeline.")]
    public Task<List<TModel>> ProjectToModelAsync(
        IQueryable<TEntity> query,
        CancellationToken cancellationToken = default)
    {
        cancellationToken.ThrowIfCancellationRequested();
        return Task.FromResult(query.Select(_toModelExpression).ToList());
    }

    /// <summary>
    /// Projects and materializes entity results from a model query.
    /// Prefer provider async APIs for database queries.
    /// </summary>
    /// <param name="query">Model query to project and execute.</param>
    /// <param name="cancellationToken">Cancellation token for the operation.</param>
    /// <returns>A task containing the projected entity list.</returns>
    [Obsolete("Use ProjectToEntity(query).ToListAsync(cancellationToken) to use the provider async pipeline.")]
    public Task<List<TEntity>> ProjectToEntityAsync(
        IQueryable<TModel> query,
        CancellationToken cancellationToken = default)
    {
        cancellationToken.ThrowIfCancellationRequested();
        return Task.FromResult(query.Select(_toEntityExpression).ToList());
    }

    /// <summary>
    /// Projects an entity query and returns the first projected model item.
    /// Prefer provider async APIs for database queries.
    /// </summary>
    /// <param name="query">Entity query to project.</param>
    /// <param name="cancellationToken">Cancellation token for the operation.</param>
    /// <returns>A task containing the first projected model item, or <see langword="null"/>.</returns>
    [Obsolete("Use ProjectToModel(query).FirstOrDefaultAsync(cancellationToken) to use the provider async pipeline.")]
    public Task<TModel?> FirstOrDefaultProjectedModelAsync(
        IQueryable<TEntity> query,
        CancellationToken cancellationToken = default)
    {
        cancellationToken.ThrowIfCancellationRequested();
        return Task.FromResult(query.Select(_toModelExpression).FirstOrDefault());
    }

    /// <summary>
    /// Projects a model query and returns the first projected entity item.
    /// Prefer provider async APIs for database queries.
    /// </summary>
    /// <param name="query">Model query to project.</param>
    /// <param name="cancellationToken">Cancellation token for the operation.</param>
    /// <returns>A task containing the first projected entity item, or <see langword="null"/>.</returns>
    [Obsolete("Use ProjectToEntity(query).FirstOrDefaultAsync(cancellationToken) to use the provider async pipeline.")]
    public Task<TEntity?> FirstOrDefaultProjectedEntityAsync(
        IQueryable<TModel> query,
        CancellationToken cancellationToken = default)
    {
        cancellationToken.ThrowIfCancellationRequested();
        return Task.FromResult(query.Select(_toEntityExpression).FirstOrDefault());
    }

    // =========================================================
    // EXPRESSIONS
    // =========================================================

    /// <summary>
    /// Returns the entity-to-model projection expression.
    /// </summary>
    /// <returns>Expression that can be used in LINQ query translation.</returns>
    public Expression<Func<TEntity, TModel>> ToModelExpression()
        => _toModelExpression;

    /// <summary>
    /// Returns the model-to-entity projection expression.
    /// </summary>
    /// <returns>Expression that can be used in LINQ query translation.</returns>
    public Expression<Func<TModel, TEntity>> ToEntityExpression()
        => _toEntityExpression;

    public Expression<Func<TEntity, NameValuePair<IdType>>> ToNameValueExpression() { 
    
        if(_toNameValueExpression == null)
            throw new NotImplementedException($"NameValue projection is not configured for {typeof(TEntity).Name} mapper.");

        return _toNameValueExpression;
    }

    // =========================================================
    // IN-PLACE MAPPING
    // =========================================================

    /// <summary>
    /// Maps entity values into an existing model instance.
    /// </summary>
    /// <param name="source">Entity object with the new values.</param>
    /// <param name="destination">Model object to mutate.</param>
    public virtual void UpdateModel(TEntity source, TModel destination)
    {
        var mapped = _toModel(source);
        CopyProperties(mapped, destination);
    }

    /// <summary>
    /// Maps model values into an existing entity instance.
    /// </summary>
    /// <param name="source">Model object with the new values.</param>
    /// <param name="destination">Entity object to mutate.</param>
    public virtual void UpdateEntity(TModel source, TEntity destination)
    {
        var mapped = _toEntity(source);
        CopyProperties(mapped, destination);
    }

    // =========================================================
    // INTERNAL HELPERS
    // =========================================================

    /// <summary>
    /// Copies readable/writable property values from one instance to another.
    /// </summary>
    /// <param name="from">Object to copy values from.</param>
    /// <param name="to">Object to copy values to.</param>
    protected virtual void CopyProperties<T>(T from, T to)
    {
        if (from == null || to == null) return;

        var props = typeof(T).GetProperties()
            .Where(p => p.CanRead && p.CanWrite);

        foreach (var prop in props)
        {
            var value = prop.GetValue(from);
            prop.SetValue(to, value);
        }
    }
}
